/usr/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re
zones={}
for i in range(1,32):
 d=Path(f'pc{i}/etc/bind'); conf=(d/'named.conf').read_text(); z=re.search(r'zone \"(["'^"]+)"'"',conf).group(1); file=re.search(r'file \"/etc/bind/(["'^"]+)"'"',conf).group(1); lines=(d/file).read_text().splitlines(); zones[z]=(i,lines)
assert len(zones)==31
count=0
for z,(i,lines) in zones.items():
 for line in lines:
  parts=line.split()
  if len(parts)==4 and parts[1:3]==['IN','NS'] and parts[0]"'!='"'@':
   child=parts[0][:-1]; target=parts[3]; j,childlines=zones[child]; ip=re.search(r'inet ([0-9.]+)/24',Path(f'pc{j}.startup').read_text()).group(1)
   assert f'@ IN NS {target}' in childlines and f'{target} IN A {ip}' in lines and f'{target} IN A {ip}' in childlines
   count+=1
assert count==30
for i in range(16,32):
 z=next(z for z,(j,_) in zones.items() if j==i); ip=re.search(r'inet ([0-9.]+)/24',Path(f'pc{i}.startup').read_text()).group(1); assert f'@ IN A {ip}' in zones[z][1]
for z in ['company.com','university.edu']:
 i,lines=zones[z]; ip=re.search(r'inet ([0-9.]+)/24',Path(f'pc{i}.startup').read_text()).group(1); assert f'@ IN MX 10 mail.{z}.' in lines and f'mail IN A {ip}' in lines
print('Static checks passed: 31 zones, 30 matching delegations and glue records, 16 service addresses, MX targets.')
PY"

